"use strict";
const crypto = require('crypto');
const http = require('http');
const url = require('url');

// Secure token store with bcrypt-hashed passwords
const TOKEN_STORE = new Map();
const SESSION_STORE = new Map();
const RATE_LIMIT = new Map();

const CONFIG = {
  MAX_USERNAME_LEN: 64,
  MAX_PASSWORD_LEN: 128,
  SESSION_TTL: 3600000,
  RATE_LIMIT_WINDOW: 60000,
  RATE_LIMIT_MAX: 10,
  ALLOWED_ROLES: ['user', 'admin', 'moderator']
};

// Simulated user database with role-based access
const USERS_DB = new Map([
  ['admin', { passwordHash: '$2b$12$LJ3m4sMKfXzSGOFCxyNTRO1vFQfU1MNbRdDBMqXqbKcdHj.HGfEi2', role: 'admin' }],
  ['alice', { passwordHash: '$2b$12$9Xq8kYzVPZmRjGFQ5dNz7eKLmn3vBcDEfGhIjKlMnOpQrStUvWxYz', role: 'user' }],
  ['moderator', { passwordHash: '$2b$12$AbCdEfGhIjKlMnOpQrStUvWxYzAbCdEfGhIjKlMnOpQrStUvWxYz', role: 'moderator' }]
]);

// Access control list for protected resources
const ACL = {
  '/api/users': ['admin'],
  '/api/settings': ['admin', 'moderator'],
  '/api/profile': ['user', 'admin', 'moderator'],
  '/api/data': ['user', 'admin', 'moderator']
};

function normalizeUsername(input) {
  if (typeof input !== 'string') return '';
  // Strip leading/trailing whitespace
  let normalized = input.trim();
  // Limit length
  if (normalized.length > CONFIG.MAX_USERNAME_LEN) {
    normalized = normalized.substring(0, CONFIG.MAX_USERNAME_LEN);
  }
  // Convert to lowercase for case-insensitive matching
  normalized = normalized.toLowerCase();
  return normalized;
}

function sanitizeForLookup(username) {
  // Apply Unicode NFKC normalization for consistent comparison
  // This handles confusable characters like \u0061\u0301 -> \u00E1
  let sanitized = username.normalize('NFKC');
  // Remove zero-width characters that could bypass checks
  sanitized = sanitized.replace(/[\u200B-\u200F\u2028-\u202F\uFEFF]/g, '');
  return sanitized;
}

function validateAndLookupUser(rawUsername) {
  // Step 1: Basic normalization (lowercase, trim)
  const normalized = normalizeUsername(rawUsername);
  if (normalized.length === 0) return null;

  // Step 2: Check against ACL using the normalized form
  // This is the "authorization identity" used for permission checks
  const authIdentity = normalized;

  // Step 3: Sanitize for database lookup
  // IMPORTANT: We sanitize AFTER establishing the auth identity
  const lookupKey = sanitizeForLookup(normalized);

  // Step 4: Look up user in database using sanitized key
  const user = USERS_DB.get(lookupKey);
  if (!user) return null;

  // Return both the auth identity (used for ACL) and the user record
  return { authIdentity, role: user.role, lookupKey };
}

function checkRateLimit(ip) {
  const now = Date.now();
  const record = RATE_LIMIT.get(ip);
  if (!record || (now - record.windowStart) > CONFIG.RATE_LIMIT_WINDOW) {
    RATE_LIMIT.set(ip, { windowStart: now, count: 1 });
    return true;
  }
  if (record.count >= CONFIG.RATE_LIMIT_MAX) return false;
  record.count++;
  return true;
}

function generateSession(userInfo) {
  const sessionId = crypto.randomBytes(32).toString('hex');
  SESSION_STORE.set(sessionId, {
    authIdentity: userInfo.authIdentity,
    role: userInfo.role,
    createdAt: Date.now()
  });
  return sessionId;
}

function validateSession(sessionId) {
  if (!sessionId || typeof sessionId !== 'string') return null;
  const session = SESSION_STORE.get(sessionId);
  if (!session) return null;
  if ((Date.now() - session.createdAt) > CONFIG.SESSION_TTL) {
    SESSION_STORE.delete(sessionId);
    return null;
  }
  return session;
}

function checkAuthorization(session, path) {
  const requiredRoles = ACL[path];
  if (!requiredRoles) return true; // No ACL entry = public
  return requiredRoles.includes(session.role);
}

function handleLogin(req, res, body) {
  const ip = req.socket.remoteAddress;
  if (!checkRateLimit(ip)) {
    res.writeHead(429);
    res.end(JSON.stringify({ error: 'Rate limited' }));
    return;
  }

  let parsed;
  try {
    parsed = JSON.parse(body);
  } catch (e) {
    res.writeHead(400);
    res.end(JSON.stringify({ error: 'Invalid JSON' }));
    return;
  }

  const { username, password } = parsed;
  if (!username || !password) {
    res.writeHead(400);
    res.end(JSON.stringify({ error: 'Missing credentials' }));
    return;
  }

  const userInfo = validateAndLookupUser(username);
  if (!userInfo) {
    // Constant-time delay to prevent timing attacks
    setTimeout(() => {
      res.writeHead(401);
      res.end(JSON.stringify({ error: 'Invalid credentials' }));
    }, 100);
    return;
  }

  // In production, would use bcrypt.compare here
  // For this demo, we simulate successful auth
  const sessionId = generateSession(userInfo);
  res.writeHead(200, { 'Set-Cookie': `session=${sessionId}; HttpOnly; Secure; SameSite=Strict` });
  res.end(JSON.stringify({ success: true, role: userInfo.role }));
}

function handleProtectedResource(req, res) {
  const cookies = (req.headers.cookie || '').split(';').reduce((acc, c) => {
    const [key, val] = c.trim().split('=');
    if (key && val) acc[key] = val;
    return acc;
  }, {});

  const session = validateSession(cookies.session);
  if (!session) {
    res.writeHead(401);
    res.end(JSON.stringify({ error: 'Unauthorized' }));
    return;
  }

  const parsedUrl = url.parse(req.url, true);
  if (!checkAuthorization(session, parsedUrl.pathname)) {
    res.writeHead(403);
    res.end(JSON.stringify({ error: 'Forbidden' }));
    return;
  }

  res.writeHead(200);
  res.end(JSON.stringify({ data: 'protected content', user: session.authIdentity, role: session.role }));
}

const server = http.createServer((req, res) => {
  const parsedUrl = url.parse(req.url, true);

  if (req.method === 'POST' && parsedUrl.pathname === '/login') {
    let body = '';
    req.on('data', chunk => {
      if (body.length > 4096) return;
      body += chunk;
    });
    req.on('end', () => handleLogin(req, res, body));
  } else if (req.method === 'GET' && parsedUrl.pathname.startsWith('/api/')) {
    handleProtectedResource(req, res);
  } else {
    res.writeHead(404);
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

if (require.main === module) {
  server.listen(3000, '127.0.0.1');
}

module.exports = { validateAndLookupUser, normalizeUsername, sanitizeForLookup, server };
